reference_solution:
def pathSum(root, t):
    res, path = [], []
    def dfs(n, rem):
        if not n:
            return
        path.append(n.val)
        if not n.left and not n.right and n.val == rem:
            res.append(path[:])
        dfs(n.left, rem - n.val)
        dfs(n.right, rem - n.val)
        path.pop()
    dfs(root, t)
    return res

brute_force_solution:
def pathSum(root, t):
    if not root:
        return []
    out = []
    q = [(root, [root.val])]
    for n, p in q:
        if not n.left and not n.right and sum(p) == t:
            out.append(p)
        if n.left:
            q.append((n.left, p + [n.left.val]))
        if n.right:
            q.append((n.right, p + [n.right.val]))
    return out

